/* HuntsmanSec portfolio interactions.
 * - Tag filters on collection pages
 * - Accessible quick-view modals
 * - Navigation dropdown
 * - Hero title scramble
 * - Interactive terminal (data generated by Jekyll in #site-data)
 * - Interactive career timeline
 */
(() => {
  "use strict";

  const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const readSiteData = () => {
    const node = document.getElementById("site-data");
    if (!node) return { sections: [], certifications: [] };
    try {
      return JSON.parse(node.textContent);
    } catch (error) {
      return { sections: [], certifications: [] };
    }
  };

  const siteData = readSiteData();

  const escapeHtml = (value) => String(value).replace(/[&<>'"]/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "'": "&#39;",
    "\"": "&quot;"
  }[character]));

  /* ---------- Tag filters ---------- */
  document.querySelectorAll("[data-filter-root]").forEach((root) => {
    const buttons = [...root.querySelectorAll("[data-filter]")];
    const cards = [...root.querySelectorAll("[data-tags]")];
    const emptyState = root.querySelector("[data-empty-state]");

    buttons.forEach((button) => {
      button.addEventListener("click", () => {
        const filter = button.dataset.filter;
        let visibleCount = 0;

        buttons.forEach((item) => {
          item.classList.toggle("active", item === button);
          item.setAttribute("aria-pressed", String(item === button));
        });

        cards.forEach((card) => {
          const tags = card.dataset.tags.split(" ").filter(Boolean);
          const isVisible = filter === "all" || tags.includes(filter);
          card.hidden = !isVisible;
          if (isVisible) visibleCount += 1;
        });

        if (emptyState) emptyState.hidden = visibleCount !== 0;
      });
    });
  });

  /* ---------- Modals ---------- */
  let lastFocused = null;
  const focusableSelector = "a[href], button:not([disabled]), input, select, textarea, [tabindex]:not([tabindex='-1'])";

  const closeModal = (modal) => {
    modal.classList.remove("open");
    modal.setAttribute("aria-hidden", "true");
    if (!document.querySelector(".modal.open")) document.body.classList.remove("modal-active");
    if (lastFocused) lastFocused.focus();
  };

  document.querySelectorAll("[data-modal-open]").forEach((button) => {
    button.addEventListener("click", () => {
      const modal = document.getElementById(button.dataset.modalOpen);
      if (!modal) return;

      lastFocused = button;
      modal.classList.add("open");
      modal.setAttribute("aria-hidden", "false");
      document.body.classList.add("modal-active");

      const closeButton = modal.querySelector(".modal-close");
      if (closeButton) closeButton.focus();
    });
  });

  document.querySelectorAll("[data-modal-close]").forEach((button) => {
    button.addEventListener("click", () => {
      const modal = button.closest(".modal");
      if (modal) closeModal(modal);
    });
  });

  document.addEventListener("keydown", (event) => {
    const openModal = document.querySelector(".modal.open");
    if (!openModal) return;

    if (event.key === "Escape") {
      closeModal(openModal);
      return;
    }

    if (event.key === "Tab") {
      const focusable = [...openModal.querySelectorAll(focusableSelector)].filter((el) => el.offsetParent !== null);
      if (focusable.length === 0) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    }
  });

  /* ---------- Navigation dropdown ---------- */
  document.querySelectorAll("[data-dropdown]").forEach((dropdown) => {
    const trigger = dropdown.querySelector("[data-dropdown-trigger]");
    if (!trigger) return;

    const close = () => {
      dropdown.classList.remove("open");
      trigger.setAttribute("aria-expanded", "false");
    };

    trigger.addEventListener("click", () => {
      const isOpen = dropdown.classList.toggle("open");
      trigger.setAttribute("aria-expanded", String(isOpen));
    });

    document.addEventListener("click", (event) => {
      if (!dropdown.contains(event.target)) close();
    });

    dropdown.addEventListener("keydown", (event) => {
      if (event.key !== "Escape") return;
      close();
      trigger.focus();
    });
  });

  /* ---------- Hero title scramble ---------- */
  const scrambleTarget = document.querySelector("[data-scramble]");

  if (scrambleTarget) {
    const finalText = scrambleTarget.dataset.scramble;
    const glyphs = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_#$%";

    const startScramble = () => {
      let frame = 0;
      const maxFrames = finalText.length * 5;
      scrambleTarget.classList.remove("glitch-complete");

      const scramble = () => {
        const output = finalText
          .split("")
          .map((char, index) => (frame / 5 > index ? char : glyphs[Math.floor(Math.random() * glyphs.length)]))
          .join("");

        scrambleTarget.textContent = output;
        scrambleTarget.dataset.text = output;
        frame += 1;

        if (frame <= maxFrames) {
          window.requestAnimationFrame(scramble);
          return;
        }

        scrambleTarget.textContent = finalText;
        scrambleTarget.dataset.text = finalText;
        scrambleTarget.classList.add("glitch-complete");
        window.setTimeout(startScramble, 4000);
      };

      scramble();
    };

    if (prefersReducedMotion) {
      scrambleTarget.textContent = finalText;
      scrambleTarget.dataset.text = finalText;
    } else {
      startScramble();
    }
  }

  /* ---------- Terminal ---------- */
  const sections = siteData.sections || [];
  const certifications = siteData.certifications || [];

  const aliases = {
    cert: "certifications",
    certs: "certifications",
    training: "trainings",
    speakership: "talks",
    mentorship: "talks",
    "speakership-and-mentorship": "talks",
    writeups: "ctf",
    "ctf-writeups": "ctf",
    "ctf-participation-and-writeups": "ctf",
    notes: "soc",
    "soc-notes": "soc",
    sheets: "cheatsheets",
    recognition: "recognitions",
    conference: "conferences",
    conf: "conferences",
    "career-timeline": "career",
    "~": "home",
    "/": "home"
  };

  const normalizePageName = (value) => value
    .trim()
    .toLowerCase()
    .replace(/^\/+|\/+$/g, "")
    .replace(/\s+/g, "-");

  const resolveSection = (target) => {
    const normalized = normalizePageName(target) || "home";
    const key = aliases[normalized] || aliases[target.trim()] || normalized;
    return sections.find((item) => item.key === key)
      || sections.find((item) => normalizePageName(item.title) === normalized);
  };

  const sectionList = () => sections
    .map((item) => `<button type="button" class="terminal-link" data-terminal-command="cd ${escapeHtml(item.key)}">${escapeHtml(item.title)}</button>`)
    .join("");

  const huntsmanAscii = [
    " _  _ _  _ _  _ _____ ___ __  __   _   _  _",
    "| || | || | |\\ | |_   _/ __|  \\/  | /_\\ | \\ |",
    "| __ | || |  \\| | | | \\__ \\ |\\/| |/ _ \\| .` |",
    "|_||_|\\__/|_|\\_| |_| |___/_|  |_/_/ \\_\\_|\\_|"
  ].join("\n");

  document.querySelectorAll("[data-terminal]").forEach((terminal) => {
    const output = terminal.querySelector("[data-terminal-output]");
    const form = terminal.querySelector("[data-terminal-form]");
    const input = form ? form.querySelector("input") : null;
    const history = [];
    let historyIndex = 0;

    if (!output || !form || !input) return;

    const print = (html) => {
      const line = document.createElement("div");
      line.className = "terminal-line";
      line.innerHTML = html;
      output.appendChild(line);
      terminal.classList.add("has-output");
      output.scrollTop = output.scrollHeight;
    };

    const clear = () => {
      output.innerHTML = "";
      terminal.classList.remove("has-output");
    };

    const runCommand = (rawCommand) => {
      const command = rawCommand.trim().toLowerCase();
      if (!command) return;

      if (command === "clear" || command === "cls") {
        clear();
        return;
      }

      print(`<span>$</span> ${escapeHtml(command)}`);

      if (command === "help") {
        print("Commands: whoami, ls, cd &lt;page&gt;, cert, cat flag.txt, security, clear.");
        return;
      }

      if (command === "whoami") {
        print(`<pre class="terminal-ascii">${huntsmanAscii}</pre><strong>Huntsman</strong><br><span>hacking since 2007</span>`);
        return;
      }

      if (command === "ls" || command === "sections") {
        print(`Available pages:<div class="terminal-command-grid">${sectionList()}</div>`);
        return;
      }

      if (command === "cert" || command === "certs" || command === "ls certs") {
        if (certifications.length === 0) {
          print("No certifications published yet.");
          return;
        }
        print(`<strong>Certifications (${certifications.length})</strong><br>${certifications.map((item) => escapeHtml(item.title)).join("<br>")}`);
        return;
      }

      if (command === "cat flag.txt") {
        print("<strong>hunt{p0w3r_b3l0ngs_2d_p30pl3_th4t_t4k3_it}</strong>");
        return;
      }

      if (command === "security") {
        print("Publishing mode: public-safe. No .env files, private keys, tokens, customer data, internal screenshots, tenant IDs, or live infrastructure details.");
        return;
      }

      const directoryCommand = command.match(/^(?:cd|open)\s*(.*)$/);
      if (directoryCommand) {
        const target = directoryCommand[1] || "~";
        const item = resolveSection(target);

        if (item) {
          window.location.assign(item.path);
          return;
        }

        print(`No page named <strong>${escapeHtml(target)}</strong>. Run <strong>ls</strong> to list pages.`);
        return;
      }

      const item = resolveSection(command);
      if (item) {
        print(`<strong>${escapeHtml(item.title)}</strong> &mdash; run <strong>cd ${escapeHtml(item.key)}</strong> to open it.`);
        return;
      }

      print(`Command not found: <strong>${escapeHtml(command)}</strong>. Type <strong>help</strong>.`);
    };

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      if (input.value.trim()) {
        history.push(input.value);
        historyIndex = history.length;
      }
      runCommand(input.value);
      input.value = "";
    });

    input.addEventListener("keydown", (event) => {
      if (event.key === "ArrowUp" && history.length > 0) {
        event.preventDefault();
        historyIndex = Math.max(0, historyIndex - 1);
        input.value = history[historyIndex];
      } else if (event.key === "ArrowDown" && history.length > 0) {
        event.preventDefault();
        historyIndex = Math.min(history.length, historyIndex + 1);
        input.value = history[historyIndex] || "";
      } else if (event.key === "Escape") {
        clear();
      } else if (event.key === "l" && event.ctrlKey) {
        event.preventDefault();
        clear();
      }
    });

    output.addEventListener("click", (event) => {
      const button = event.target.closest("[data-terminal-command]");
      if (!button) return;
      runCommand(button.dataset.terminalCommand);
    });
  });

  /* ---------- Career timeline ---------- */
  const monthIndex = (value) => {
    if (!value) return null;
    if (value === "present") {
      const now = new Date();
      return now.getFullYear() * 12 + now.getMonth();
    }
    const match = /^(\d{4})-(\d{2})/.exec(value);
    return match ? Number(match[1]) * 12 + Number(match[2]) - 1 : null;
  };

  const formatDuration = (months) => {
    const years = Math.floor(months / 12);
    const rest = months % 12;
    const parts = [];
    if (years) parts.push(`${years} yr${years > 1 ? "s" : ""}`);
    if (rest) parts.push(`${rest} mo${rest > 1 ? "s" : ""}`);
    return parts.join(" ") || "1 mo";
  };

  document.querySelectorAll("[data-career]").forEach((root) => {
    const entries = [...root.querySelectorAll("[data-career-entry]")];
    const filters = [...root.querySelectorAll("[data-career-filter]")];
    const overview = root.querySelector("[data-career-overview]");
    const axis = root.querySelector("[data-career-axis]");
    const rows = root.querySelector("[data-career-rows]");
    root.classList.add("is-enhanced");

    const setExpanded = (entry, expanded) => {
      const toggle = entry.querySelector("[data-career-toggle]");
      const details = entry.querySelector("[data-career-details]");
      if (!toggle || !details) return;
      toggle.setAttribute("aria-expanded", String(expanded));
      details.hidden = !expanded;
      entry.classList.toggle("is-open", expanded);
    };

    const focusEntry = (entry) => {
      setExpanded(entry, true);
      entry.scrollIntoView({ behavior: prefersReducedMotion ? "auto" : "smooth", block: "center" });
      entry.classList.add("is-highlighted");
      window.setTimeout(() => entry.classList.remove("is-highlighted"), 1600);
      const toggle = entry.querySelector("[data-career-toggle]");
      if (toggle) toggle.focus({ preventScroll: true });
      if (window.history.replaceState) window.history.replaceState(null, "", `#${entry.id}`);
    };

    // Durations + collapsed initial state
    entries.forEach((entry) => {
      const start = monthIndex(entry.dataset.start);
      const end = monthIndex(entry.dataset.end);
      const durationNode = entry.querySelector("[data-career-duration]");
      if (start !== null && end !== null && durationNode) {
        durationNode.textContent = formatDuration(Math.max(1, end - start + 1));
      }
      setExpanded(entry, false);
    });

    // Toggle + keyboard navigation between roles
    root.addEventListener("click", (event) => {
      const toggle = event.target.closest("[data-career-toggle]");
      if (!toggle) return;
      const entry = toggle.closest("[data-career-entry]");
      setExpanded(entry, toggle.getAttribute("aria-expanded") !== "true");
    });

    root.addEventListener("keydown", (event) => {
      const toggle = event.target.closest("[data-career-toggle]");
      if (!toggle || !["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) return;
      const visible = entries.filter((entry) => !entry.hidden).map((entry) => entry.querySelector("[data-career-toggle]"));
      const index = visible.indexOf(toggle);
      let next = null;
      if (event.key === "ArrowDown") next = visible[index + 1];
      if (event.key === "ArrowUp") next = visible[index - 1];
      if (event.key === "Home") next = visible[0];
      if (event.key === "End") next = visible[visible.length - 1];
      if (next) {
        event.preventDefault();
        next.focus();
      }
    });

    const expandAll = root.querySelector("[data-career-expand-all]");
    const collapseAll = root.querySelector("[data-career-collapse-all]");
    if (expandAll) expandAll.addEventListener("click", () => entries.filter((e) => !e.hidden).forEach((e) => setExpanded(e, true)));
    if (collapseAll) collapseAll.addEventListener("click", () => entries.forEach((e) => setExpanded(e, false)));

    // Overview chart
    const spans = entries
      .map((entry) => ({ entry, start: monthIndex(entry.dataset.start), end: monthIndex(entry.dataset.end) }))
      .filter((item) => item.start !== null && item.end !== null);

    if (overview && axis && rows && spans.length > 0) {
      const firstYear = Math.floor(Math.min(...spans.map((s) => s.start)) / 12);
      const lastYear = Math.floor(Math.max(...spans.map((s) => s.end)) / 12) + 1;
      const min = firstYear * 12;
      const total = lastYear * 12 - min;
      const pct = (value) => `${((value - min) / total) * 100}%`;

      for (let year = firstYear; year < lastYear; year += 1) {
        const tick = document.createElement("span");
        tick.style.left = pct(year * 12);
        tick.textContent = String(year);
        axis.appendChild(tick);
      }

      [...spans].sort((a, b) => a.start - b.start).forEach(({ entry, start, end }) => {
        const bar = document.createElement("button");
        bar.type = "button";
        bar.className = "career-bar";
        bar.dataset.track = entry.dataset.track;
        bar.style.setProperty("--track", entry.style.getPropertyValue("--track"));
        bar.style.left = pct(start);
        bar.style.width = `calc(${((end - start + 1) / total) * 100}% - 2px)`;
        bar.setAttribute("aria-label", `${entry.dataset.title}, ${entry.dataset.org}`);
        bar.innerHTML = `<span>${escapeHtml(entry.dataset.title)}</span>`;
        bar.title = `${entry.dataset.title} · ${entry.dataset.org}`;
        if (entry.dataset.end === "present") bar.classList.add("is-current");
        bar.addEventListener("click", () => {
          if (entry.hidden) applyFilter("all");
          focusEntry(entry);
        });
        bar.addEventListener("mouseenter", () => entry.classList.add("is-hovered"));
        bar.addEventListener("mouseleave", () => entry.classList.remove("is-hovered"));
        rows.appendChild(bar);
        entry._bar = bar;
      });

      overview.hidden = false;

      // Bars too narrow for their label show it beside the bar instead.
      const labelNarrowBars = () => {
        rows.querySelectorAll(".career-bar").forEach((bar) => {
          bar.classList.remove("is-narrow", "label-right");
          const label = bar.querySelector("span");
          if (label && label.scrollWidth > bar.clientWidth - 12) {
            bar.classList.add("is-narrow");
            if (parseFloat(bar.style.left) < 50) bar.classList.add("label-right");
          }
        });
      };
      labelNarrowBars();
      window.addEventListener("resize", labelNarrowBars);
    }

    // Track filters
    const applyFilter = (track) => {
      filters.forEach((button) => {
        const active = button.dataset.careerFilter === track;
        button.classList.toggle("active", active);
        button.setAttribute("aria-pressed", String(active));
      });
      entries.forEach((entry) => {
        const visible = track === "all" || entry.dataset.track === track;
        entry.hidden = !visible;
        if (entry._bar) entry._bar.classList.toggle("is-dimmed", !visible);
      });
    };

    filters.forEach((button) => {
      button.addEventListener("click", () => applyFilter(button.dataset.careerFilter));
    });

    // Deep link: /career/#role-xyz opens that role
    if (window.location.hash) {
      const target = root.querySelector(window.location.hash.replace(/[^#\w-]/g, ""));
      if (target && target.matches("[data-career-entry]")) window.setTimeout(() => focusEntry(target), 150);
    }
  });
})();
